    # For simplicity, let's add a new TYPE_CHECKING block at the right location
    # Find where to place the TYPE_CHECKING block - after the last import but before other statements
    import_end_index = 0
    for i, statement in enumerate(module.body):
        if isinstance(statement, (libcst.Import, libcst.ImportFrom)):
            import_end_index = i + 1
        elif isinstance(statement, libcst.SimpleStatementLine):
            # Check if it's an import-like statement
            for item in statement.body:
                if isinstance(item, (libcst.Import, libcst.ImportFrom)):
                    import_end_index = i + 1

    # Insert TYPE_CHECKING block after imports but before other statements
    # But first, let's make sure we don't duplicate TYPE_CHECKING imports
    # Actually, let's just create a clean TYPE_CHECKING block

